import sys; sys.path.insert(0,"/app/work")
from lib3 import *
boxes=extract_boxes()
owner=build_owner(boxes)

def trace(b, direction, maxgap=2):
    """direction=-1 up, +1 down. Returns ('bar', r, c) or ('box', boxidx, r, c) or ('fail', ...)"""
    c = b['cc']
    r = (b['Tb'] if direction<0 else b['Bb']) + direction
    gap=0
    steps=0
    while 5 <= r < 110 and steps < 40:
        steps+=1
        o = owner[r][c]
        if o>=0 and o!=b['i']:
            return ('box', o, r, c)
        ch = grid[r][c]
        if ch=='+':
            return ('bar', r, c)
        if ch in '-~':
            return ('bar', r, c)
        if ch in VERT:
            gap=0; r+=direction; continue
        # check neighbors +-1
        moved=False
        for d in (-1,1):
            cn=c+d
            if 0<=cn<W:
                o2=owner[r][cn]
                if o2>=0 and o2!=b['i']: return ('box', o2, r, cn)
                c2=grid[r][cn]
                if c2=='+': return ('bar', r, cn)
                if c2 in VERT:
                    c=cn; gap=0; r+=direction; moved=True; break
        if moved: continue
        if ch==' ':
            # maybe degraded junction on a bar row?
            if bar_strength(r,c) >= 8:
                return ('bar', r, c)
            gap+=1
            if gap>maxgap: return ('fail', r, c)
            r+=direction; continue
        return ('fail', r, c)
    return ('fail', r, c)

up={}; down={}
for b in boxes:
    up[b['i']]=trace(b,-1)
    down[b['i']]=trace(b,+1)
print("UP kinds:", Counter(v[0] for v in up.values()))
print("DOWN kinds:", Counter(v[0] for v in down.values()))
for b in boxes:
    if up[b['i']][0]!='bar':
        print("  UPFAIL", b['name'], b['rt'], b['cc'], up[b['i']])
EOF
