            if grid[r][L]=='+' and grid[r][R]=='+': B=r;break
        if B is None:
            for r in range(rb+1, min(H,rb+4)):
                seg=grid[r][L:R+1]
                if WORD.search(seg): continue
                if sum(1 for c in seg if c in HB)>=0.5*len(seg): B=r;break
        if B is None: B=rb+1
        T=None; r=rt-1
        while r>=0:
            if grid[r][L]=='+' and grid[r][R]=='+': T=r; break
            if grid[r][L] in VERT or grid[r][R] in VERT: r-=1; continue
            break
        Tb = T if T is not None else r+1
        cc = (L+R)//2
        boxes.append(dict(i=bi,name=name,rt=rt,rb=rb,cl=cl,ch=ch,L=L,R=R,cc=cc,
                          T=T,B=B,Tb=Tb,Bb=B))
    return boxes

def build_owner(boxes):
    owner=[[-1]*W for _ in range(H)]
    for b in boxes:
        for r in range(b['Tb'], b['Bb']+1):
            for c in range(b['L'], b['R']+1):
                owner[r][c]=b['i']
    return owner

def trace_stem(b, direction, owner, maxgap=2, tol=2):
    """Follow the stem from box edge; return (row,col) where it meets a bar, else None."""
    r0 = (b['Tb']-1) if direction<0 else (b['Bb']+1)
    # choose starting column: nearest vertical ink to cc
    cands=[]
    for d in range(0, tol+1):
        for s in ((0,) if d==0 else (-d, d)):
            c=b['cc']+s
            if 0<=c<W and grid[r0][c] in VERT: cands.append(c)
    if not cands:
        # maybe the bar is immediately adjacent (box sits right on bar)
        for d in range(0, tol+1):
            for s in ((0,) if d==0 else (-d,d)):
                c=b['cc']+s
                if 0<=c<W and grid[r0][c] in HB: return (r0,c)
        return None
    c=cands[0]; r=r0; gap=0
    while R0-1 <= r < R1+1:
        ch=grid[r][c]
        if ch in HB: return (r,c)
        if ch in VERT:
            gap=0; r+=direction; continue
        if ch==' ':
            moved=False
            for d in (-1,1):
                cn=c+d
                if 0<=cn<W and grid[r][cn] in VERT:
                    c=cn; gap=0; moved=True; break
                if 0<=cn<W and grid[r][cn] in HB:
                    return (r,cn)
            if moved: r+=direction; continue
            gap+=1
            if gap>maxgap: return None
            r+=direction; continue
        return None
    return None
EOF
