import sys; sys.path.insert(0,"/app/work")
from lib7 import *
import json

boxes,owner,up,dn,find_run,RR=build()
name={b['i']:b['name'] for b in boxes}
N=len(boxes)

parent={}   # child -> parent
# 1) direct box-to-box links (child's up-stem lands on a box)
barkids=defaultdict(list)
for b in boxes:
    i=b['i']; v=up[i]
    if v is None: continue
    o=owner[v[0]][v[1]]
    if o!=-1 and o!=i:
        parent[i]=o
    else:
        k=find_run(*v)
        if k: barkids[k].append(i)
        else: print("WARN child with no bar:",name[i],v)

# 2) bars: find the parent whose down-stem lands on the same bar, or whose box sits above it
barparent={}
for b in boxes:
    i=b['i']; v=dn[i]
    if v is None: continue
    o=owner[v[0]][v[1]]
    if o!=-1 and o!=i: continue   # direct link handled from child side
    k=find_run(*v)
    if k: barparent.setdefault(k,[]).append(i)

unres=[]
for k,kids in barkids.items():
    ps=barparent.get(k,[])
    if len(ps)==1:
        for c in kids: parent[c]=ps[0]
    else:
        unres.append((k,kids,ps))
print("edges so far:",len(parent),"unresolved bars:",len(unres))
for k,kids,ps in unres:
    print("  bar",k,"kids:",[name[i] for i in kids],"parents:",[name[i] for i in ps])
json.dump({"parent":{str(k):v for k,v in parent.items()},"name":{str(k):v for k,v in name.items()}},open("g1.json","w"),ensure_ascii=False)
EOF
