cat > robust.py <<'EOF'
import sys; sys.path.insert(0,"/app/work")
from lib8 import *
import csv
BALC={(r["first_name"]+" "+r["last_name"]):int(r["account_balance"])
      for r in csv.DictReader(open("/app/dataset/people_accounts.csv",encoding="utf-8"))}
def gap_between(r,lo,hi,owner):
    gaps=[];run=0
    for c in range(lo+1,hi):
        if grid[r][c] in HB and owner[r][c]==-1:
            if run: gaps.append(run)
            run=0
        else: run+=1
    if run: gaps.append(run)
    return max(gaps) if gaps else 0
def full(gt):
    boxes,owner,up,dn,find_run,RR=build(gt)
    name={b['i']:b['name'] for b in boxes}; B={b['i']:b for b in boxes}
    idx={v:k for k,v in name.items()}
    bk=defaultdict(list); bp=defaultdict(list); parent={}
    for b in boxes:
        i=b['i']; v=up[i]
        if v is None: continue
        o=owner[v[0]][v[1]]
        if o!=-1 and o!=i: parent[i]=o
        else:
            k=find_run(*v)
            if k: bk[k].append((v[1],i))
    for b in boxes:
        i=b['i']; v=dn[i]
        if v is None: continue
        o=owner[v[0]][v[1]]
        if o!=-1 and o!=i: continue
        k=find_run(*v)
        if k: bp[k].append((v[1],i))
    unp=0
    for k,kids in bk.items():
        r,_,_=k; pars=sorted(bp.get(k,[])); kids=sorted(kids)
        if not pars: unp+=len(kids); continue
        if len(pars)==1:
            for _,i in kids: parent[i]=pars[0][1]
            continue
        cuts=[]
        for a in range(len(pars)-1):
            p1,p2=pars[a][0],pars[a+1][0]
