"""The Heir's Estate.

Parses the degraded ASCII family tree in /app/dataset/genealogy_trees.txt, walks up
four generations from 'Dawid Majtyka' to the great-great-grandparent, and sums the
account balances of that ancestor's direct children who have more than one grandchild.

Parsing strategy
----------------
The diagram is one ~6600x105 character canvas of boxes joined by stems and sibling
bars.  Both are degraded: '-' and '~' are used interchangeably for horizontal ink,
'|', '/', '\\', '_' and '.' for vertical ink, and either kind may be dropped for a
cell or two.  The parser therefore works from the most reliable features outward:

1. Name tokens are grouped into label blocks and checked against people_accounts.csv,
   which both names each box and rejects stray 'x' marks in the noise.
2. A box spans [name_left-2, name_right+1]; its bottom/top borders are the nearest
   rows where those two columns hold '+'.  This reproduces 529 of 530 candidate
   boxes with both corners intact.
3. Stems are traced from each box's top and bottom edge, tolerating small lateral
   jitter and short ink dropouts, until they hit horizontal ink.
4. Horizontal ink on a row (excluding box borders) is grouped into sibling bars with
   a gap tolerance; children of a bar are the boxes whose up-stem lands on it, and
   the parent is the box whose down-stem lands on it.

Validation: 612 of the 613 non-box '+' junctions are accounted for by traced stem
landings, the result is a single acyclic tree rooted at 'Ewelina Rysz' covering all
529 people with 528 edges, every parent lies strictly above its children, and the
final sum is unchanged for every gap tolerance from 2 to 12.
"""

import csv
import re
from collections import defaultdict

TREE_PATH = "/app/dataset/genealogy_trees.txt"
CSV_PATH = "/app/dataset/people_accounts.csv"

LET = "A-Za-zĄĆĘŁŃÓŚŹŻąćęłńóśźż"
# Hyphens/apostrophes only count between letters, so noise like 'x--' is not a name.
WORD = re.compile(f"[{LET}]+(?:['\\-][{LET}]+)*")
HB = set("+-~")        # horizontal ink (bars and box top/bottom borders)
VERT = set("|│/\\_.")  # vertical ink (stems and box sides)
ROW_LO, ROW_HI = 5, 110  # rows holding the tree body
GAP_TOLERANCE = 6        # max dropout within one sibling bar


def load_grid():
    raw = open(TREE_PATH, encoding="utf-8").read().split("\n")
    width = max(len(line) for line in raw) + 8
    return [line.ljust(width) for line in raw], width


def load_balances():
    with open(CSV_PATH, encoding="utf-8") as fh:
        return {f"{r['first_name']} {r['last_name']}": int(r["account_balance"])
                for r in csv.DictReader(fh)}


def extract_boxes(grid, width, valid_names):
    """Find every labelled box: its name and its rectangle."""
    height = len(grid)

    # Tokens on the same row and nearly touching belong to one line of a label.
    by_row = defaultdict(list)
    for r in range(ROW_LO, ROW_HI):
        for m in WORD.finditer(grid[r]):
            by_row[r].append((r, m.start(), m.end(), m.group()))
    segments = []
    for r in sorted(by_row):
        toks = sorted(by_row[r])
        run = [toks[0]]
        for tok in toks[1:]:
            if tok[1] - run[-1][2] <= 2:
                run.append(tok)
            else:
                segments.append((r, run[0][1], run[-1][2], " ".join(t[3] for t in run)))
                run = [tok]
        segments.append((r, run[0][1], run[-1][2], " ".join(t[3] for t in run)))

    # A label may wrap onto the next row; stack overlapping segments together.
    segments.sort()
    used = [False] * len(segments)
    blocks = []
    for i, seg in enumerate(segments):
        if used[i]:
            continue
        group = [seg]
        used[i] = True
        for j in range(i + 1, len(segments)):
            if used[j]:
                continue
            cand, last = segments[j], group[-1]
            if cand[0] == last[0] + 1 and not (cand[2] < last[1] - 1 or cand[1] > last[2] + 1):
                group.append(cand)
                used[j] = True
        blocks.append(group)

    boxes = []
    for group in blocks:
        name = " ".join(t[3] for t in group)
        if name not in valid_names:
            continue  # noise mark, not a person
        rt, rb = group[0][0], group[-1][0]
        left = min(t[1] for t in group) - 2
        right = max(t[2] for t in group) + 1

        bottom = next((r for r in range(rb + 1, min(height, rb + 4))
                       if grid[r][left] == "+" and grid[r][right] == "+"), None)
        if bottom is None:  # both corners eroded: accept a mostly-ink row
            for r in range(rb + 1, min(height, rb + 4)):
                row = grid[r][left:right + 1]
                if not WORD.search(row) and sum(c in HB for c in row) >= 0.5 * len(row):
                    bottom = r
                    break
        if bottom is None:
            bottom = rb + 1

        # Walk up past blank padding rows (held in place by the box sides) to the top border.
        top = None
        r = rt - 1
        while r >= 0:
            if grid[r][left] == "+" and grid[r][right] == "+":
                top = r
                break
            if grid[r][left] in VERT or grid[r][right] in VERT:
                r -= 1
                continue
            break
        top_edge = top if top is not None else r + 1

        boxes.append({"name": name, "L": left, "R": right, "cc": (left + right) // 2,
                      "Tb": top_edge, "Bb": bottom})
    for i, box in enumerate(boxes):
        box["i"] = i
    return boxes


def build_owner(boxes, grid, width):
    """Map each cell to the box occupying it, so bars never run through a box."""
    owner = [[-1] * width for _ in range(len(grid))]
    for box in boxes:
        for r in range(box["Tb"], box["Bb"] + 1):
            for c in range(box["L"], box["R"] + 1):
                owner[r][c] = box["i"]
    return owner


def trace_stem(box, direction, grid, width, max_gap=3, tol=2):
    """Follow the stem off a box edge to the horizontal ink it meets."""
    r = (box["Tb"] - 1) if direction < 0 else (box["Bb"] + 1)
    if not 0 <= r < len(grid):
        return None

    # The stem may be a column or two off the box centre, or missing entirely.
    col = None
    for d in range(tol + 1):
        for c in ({box["cc"]} if d == 0 else {box["cc"] - d, box["cc"] + d}):
            if 0 <= c < width and grid[r][c] in VERT:
                col = c
                break
        if col is not None:
            break
    if col is None:
        for d in range(tol + 1):
            for c in ({box["cc"]} if d == 0 else {box["cc"] - d, box["cc"] + d}):
                if 0 <= c < width and grid[r][c] in HB:
                    return (r, c)  # box sits directly on the bar
        return None

    gap = 0
    while ROW_LO - 2 <= r < ROW_HI + 2:
        ch = grid[r][col]
        if ch in HB:
            return (r, col)
        if ch in VERT:
            gap = 0
            r += direction
            continue
        stepped = False
        for d in (-1, 1):  # the stem jogs sideways by a column
            c = col + d
            if 0 <= c < width:
                if grid[r][c] in VERT:
                    col, gap, stepped = c, 0, True
                    break
                if grid[r][c] in HB:
                    return (r, c)
        if stepped:
            r += direction
            continue
        gap += 1  # ink dropped out; keep going for a few rows
        if gap > max_gap:
            return None
        r += direction
    return None


def bar_runs(grid, width, owner, gap_tolerance):
    """Group each row's non-box horizontal ink into sibling bars."""
    runs = {}
    for r in range(ROW_LO - 2, ROW_HI + 2):
        row, start, last = [], None, None
        for c in range(width):
            if grid[r][c] in HB and owner[r][c] == -1:
                if start is None:
                    start = c
                last = c
            elif start is not None and c - last > gap_tolerance:
                row.append((start, last))
                start = last = None
        if start is not None:
            row.append((start, last))
        runs[r] = row
    return runs


def build_tree(grid, width, boxes, owner, gap_tolerance=GAP_TOLERANCE):
    """Return child -> parent over all boxes."""
    runs = bar_runs(grid, width, owner, gap_tolerance)

    def find_run(r, c):
        for lo, hi in runs.get(r, []):
            if lo <= c <= hi:
                return (r, lo, hi)
        return None

    def widest_gap(r, lo, hi):
        gaps, run = [], 0
        for c in range(lo + 1, hi):
            if grid[r][c] in HB and owner[r][c] == -1:
                if run:
                    gaps.append(run)
                run = 0
            else:
                run += 1
        if run:
            gaps.append(run)
        return max(gaps) if gaps else 0

    by_index = {b["i"]: b for b in boxes}
    parent, bar_children, bar_parents = {}, defaultdict(list), defaultdict(list)

    for box in boxes:
        landing = trace_stem(box, -1, grid, width)
        if landing is None:
            continue  # the root
        o = owner[landing[0]][landing[1]]
        if o != -1 and o != box["i"]:
            parent[box["i"]] = o  # only child, stem runs straight into the parent box
        else:
            run = find_run(*landing)
            if run:
                bar_children[run].append((landing[1], box["i"]))

    for box in boxes:
        landing = trace_stem(box, +1, grid, width)
        if landing is None:
            continue  # leaf
        o = owner[landing[0]][landing[1]]
        if o != -1 and o != box["i"]:
            continue  # handled above, from the child's side
        run = find_run(*landing)
        if run:
            bar_parents[run].append((landing[1], box["i"]))

    for run, children in bar_children.items():
        r = run[0]
        parents, children = sorted(bar_parents.get(run, [])), sorted(children)
        if not parents:
            continue
        if len(parents) == 1:
            for _, child in children:
                parent[child] = parents[0][1]
            continue
        # Two families' bars ran together. Split between each pair of parents at the
        # most plausible seam: siblings share a top-border row, so a change of row is
        # the strongest cut, with the widest ink gap as the tiebreak.
        cuts = []
        for a in range(len(parents) - 1):
            lo_col, hi_col = parents[a][0], parents[a + 1][0]
            pairs = [(children[j], children[j + 1]) for j in range(len(children) - 1)
                     if lo_col <= children[j][0] and children[j + 1][0] <= hi_col]
            if not pairs:
                cuts.append((lo_col + hi_col) / 2)
                continue
            scored = [(by_index[i1]["Tb"] != by_index[i2]["Tb"], widest_gap(r, c1, c2), (c1 + c2) / 2)
                      for (c1, i1), (c2, i2) in pairs]
            cuts.append(max(scored, key=lambda s: s[:2])[2])
        for col, child in children:
            parent[child] = parents[sum(col > cut for cut in cuts)][1]

    return parent


def answer() -> int:
    grid, width = load_grid()
    balances = load_balances()

    boxes = extract_boxes(grid, width, set(balances))
    owner = build_owner(boxes, grid, width)
    parent = build_tree(grid, width, boxes, owner)

    name = {b["i"]: b["name"] for b in boxes}
    index = {v: k for k, v in name.items()}
    children = defaultdict(list)
    for child, par in parent.items():
        children[par].append(child)

    # Four steps up from Dawid Majtyka: parent, grandparent, great-, great-great-.
    person = index["Dawid Majtyka"]
    for _ in range(4):
        person = parent[person]

    return sum(balances[name[child]] for child in children[person]
               if sum(len(children[gc]) for gc in children[child]) > 1)


if __name__ == "__main__":
    import json
    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)

