                    gaps.append(run)
                run = 0
            else:
                run += 1
        if run:
            gaps.append(run)
        return max(gaps) if gaps else 0

    by_index = {b["i"]: b for b in boxes}
    parent, bar_children, bar_parents = {}, defaultdict(list), defaultdict(list)

    for box in boxes:
        landing = trace_stem(box, -1, grid, width)
        if landing is None:
            continue  # the root
        o = owner[landing[0]][landing[1]]
        if o != -1 and o != box["i"]:
            parent[box["i"]] = o  # only child, stem runs straight into the parent box
        else:
            run = find_run(*landing)
            if run:
                bar_children[run].append((landing[1], box["i"]))

    for box in boxes:
        landing = trace_stem(box, +1, grid, width)
        if landing is None:
            continue  # leaf
        o = owner[landing[0]][landing[1]]
        if o != -1 and o != box["i"]:
            continue  # handled above, from the child's side
        run = find_run(*landing)
        if run:
            bar_parents[run].append((landing[1], box["i"]))

    for run, children in bar_children.items():
        r = run[0]
        parents, children = sorted(bar_parents.get(run, [])), sorted(children)
        if not parents:
            continue
        if len(parents) == 1:
            for _, child in children:
                parent[child] = parents[0][1]
            continue
        # Two families' bars ran together. Split between each pair of parents at the
        # most plausible seam: siblings share a top-border row, so a change of row is
        # the strongest cut, with the widest ink gap as the tiebreak.
        cuts = []
        for a in range(len(parents) - 1):
            lo_col, hi_col = parents[a][0], parents[a + 1][0]
            pairs = [(children[j], children[j + 1]) for j in range(len(children) - 1)
                     if lo_col <= children[j][0] and children[j + 1][0] <= hi_col]
            if not pairs:
                cuts.append((lo_col + hi_col) / 2)
                continue
            scored = [(by_index[i1]["Tb"] != by_index[i2]["Tb"], widest_gap(r, c1, c2), (c1 + c2) / 2)
                      for (c1, i1), (c2, i2) in pairs]
            cuts.append(max(scored, key=lambda s: s[:2])[2])
        for col, child in children:
            parent[child] = parents[sum(col > cut for cut in cuts)][1]

    return parent


def answer() -> int:
    grid, width = load_grid()
    balances = load_balances()

    boxes = extract_boxes(grid, width, set(balances))
    owner = build_owner(boxes, grid, width)
    parent = build_tree(grid, width, boxes, owner)

    name = {b["i"]: b["name"] for b in boxes}
    index = {v: k for k, v in name.items()}
    children = defaultdict(list)
    for child, par in parent.items():
        children[par].append(child)

    # Four steps up from Dawid Majtyka: parent, grandparent, great-, great-great-.
    person = index["Dawid Majtyka"]
    for _ in range(4):
        person = parent[person]

    return sum(balances[name[child]] for child in children[person]
               if sum(len(children[gc]) for gc in children[child]) > 1)


if __name__ == "__main__":
    import json
    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)
